  if(snapshot.matches.length>1500||snapshot.players.length>300)throw new ApiError('The unified Trace dataset is larger than expected.',413,'trace_dataset_too_large');
  const seen=new Set();for(const m of snapshot.matches){const id=clean(m?.trace_game_id);if(!id)throw new ApiError('A match is missing its Trace game ID.',400,'trace_match_id_missing');if(seen.has(id))throw new ApiError(`Duplicate match ${id} was found.`,400,'trace_duplicate_match');seen.add(id);if(!Array.isArray(m?.players)||m.players.length>120)throw new ApiError(`Match ${id} has invalid player data.`,400,'trace_match_invalid');}
