async function tenantStorageKey(owner,publicKey){const familyHash=await sha256Hex(`team-family:${clean(publicKey)}`);return `u:${clean(owner).slice(0,32)}:${familyHash.slice(0,32)}`;}
async function connection(env,key){return env.DB.prepare('SELECT * FROM trace_connections WHERE teamsnap_key=?').bind(key).first();}
async function ownedConnection(env,key,owner){return env.DB.prepare('SELECT * FROM trace_connections WHERE teamsnap_key=? AND owner_hash=?').bind(key,owner).first();}
async function authSession(env,owner){const row=await env.DB.prepare('SELECT * FROM trace_auth_sessions WHERE owner_hash=?').bind(owner).first();if(row?.cookie_header)row.cookie_header=await decryptSecret(env,row.cookie_header);return row;}
async function pendingAuth(env,owner){const row=await env.DB.prepare('SELECT * FROM trace_auth_pending WHERE owner_hash=?').bind(owner).first();if(row?.guest_cookie)row.guest_cookie=await decryptSecret(env,row.guest_cookie);return row;}
async function tenantKeyFor(env,owner,publicKey){return tenantStorageKey(owner,clean(publicKey));}

async function enforceRateLimit(env,bucket,limit,windowMs=TRACE_RATE_WINDOW_MS){const slot=Math.floor(Date.now()/windowMs),key=`${bucket}:${slot}`,expiresAt=(slot+1)*windowMs,row=await env.DB.prepare(`INSERT INTO trace_rate_limits(bucket,hits,expires_at) VALUES(?,1,?) ON CONFLICT(bucket) DO UPDATE SET hits=trace_rate_limits.hits+1,expires_at=excluded.expires_at RETURNING hits`).bind(key,expiresAt).first();if(Number(row?.hits||0)>limit)throw new ApiError('Too many attempts. Try again later.',429,'rate_limited');}

function tsCollectionObjects(payload){return(payload?.collection?.items||[]).map(item=>{const o={};for(const d of item.data||[])if(d?.name)o[d.name]=d.value;for(const l of item.links||[])if(l.rel&&!o[`_link_${l.rel}`])o[`_link_${l.rel}`]=l.href;o._href=item.href||item.links?.find(l=>l.rel==='self')?.href||null;return o;});}
function tsCollectionLink(payload,rel){return payload?.collection?.links?.find(l=>l.rel===rel)?.href||payload?.collection?.items?.flatMap(i=>i.links||[]).find(l=>l.rel===rel)?.href||null;}
async function tsJson(url,token){const res=await fetch(url,{headers:{Authorization:`Bearer ${token}`,Accept:'application/vnd.collection+json, application/json'},cache:'no-store'}),payload=await res.json().catch(()=>({}));if(res.status===401||res.status===403)throw new ApiError('TeamSnap authorization expired. Reconnect TeamSnap from /admin.',401,'teamsnap_auth_expired');if(!res.ok)throw new ApiError(payload?.collection?.error?.message||payload?.error||payload?.message||`TeamSnap request failed (${res.status}).`,502,'teamsnap_request_failed');return payload;}
async function tsFetchCollection(pathOrUrl,params,token){let url=pathOrUrl.startsWith('http')?new URL(pathOrUrl):new URL(`${TEAMSNAP_API}/${pathOrUrl.replace(/^\//,'')}`);for(const[k,v]of Object.entries(params||{}))if(v!==undefined&&v!==null&&v!=='')url.searchParams.set(k,v);if(!url.searchParams.has('page_size'))url.searchParams.set('page_size','100');const out=[],seen=new Set();for(let page=0;url&&page<250;page++){const key=url.toString();if(seen.has(key))break;seen.add(key);const payload=await tsJson(key,token);out.push(...tsCollectionObjects(payload));const next=tsCollectionLink(payload,'next');if(next){url=new URL(next);continue;}const pi=payload?.collection?.page_info;if(pi&&Number(pi.total_items)>out.length&&Number(pi.page_size)>0){url.searchParams.set('page_number',String(Number(pi.page_number??page)+1));continue;}url=null;}return out;}
function pick(o,keys){const z={};for(const k of keys)if(o?.[k]!==undefined)z[k]=o[k];return z;}
function sanitizeTeam(t){return pick(t,['id','name','team_name','label','season_name','season_label','season_title','season','season_start_date','season_end_date','start_date','end_date','starts_at','ends_at','updated_at','modified_at','created_at','created_date','created','is_archived','archived','is_retired','retired','status','location_name','location','city','state','state_code','zip','postal_code']);}
function sanitizeEvent(e){return pick(e,['id','name','formatted_title','label','is_game','start_date','start_at','starts_at','date','location_id','opponent_id','location_name','opponent_name','season_phase','season_phase_name','phase_name','event_phase','points_for_team','points_for_opponent','team_score','opponent_score','score_for','score_against','result','results','home_or_away','home_away','location_type','is_home','is_away','is_availability_enabled','availability_enabled','tracks_availability','is_availability_tracking_enabled']);}
function sanitizeMember(m){return pick(m,['id','first_name','last_name','name','label','type','member_type','role','position','position_name','sport_position_name','position_label','jersey_number','jersey','number','uniform_number','jersey_no','uniform_no','is_non_player','is_manager','is_owner','is_coach','is_player','is_active','active_status']);}
function sanitizeLocation(x){return pick(x,['id','name','label','address','city','state','state_code','zip','postal_code']);}function sanitizeOpponent(x){return pick(x,['id','name','label']);}function sanitizeAvailability(x){return pick(x,['id','event_id','member_id','status_code']);}
function sanitizeResource(resource,rows){const fn={events:sanitizeEvent,members:sanitizeMember,locations:sanitizeLocation,opponents:sanitizeOpponent,availabilities:sanitizeAvailability}[resource]||((x)=>x);return(rows||[]).map(fn);}
function discoverTsTeamUrls(payload,me){const urls=new Set(),add=l=>{if(!l?.href)return;const rel=clean(l.rel).toLowerCase();let u;try{u=new URL(l.href);}catch{return;}if(/\/teams(?:\/|$)/i.test(u.pathname)&&['teams','active_teams','archived_teams','past_teams','retired_teams','team_history'].includes(rel))urls.add(u.toString());};for(const l of payload?.collection?.links||[])add(l);for(const item of payload?.collection?.items||[])for(const l of item.links||[])add(l);for(const[k,v]of Object.entries(me||{}))if(k.startsWith('_link_')&&v)add({rel:k.slice(6),href:v});return[...urls];}
async function appConfig(env){return env.DB.prepare('SELECT * FROM app_config WHERE id=?').bind(APP_ID).first();}
async function saveTeamResource(env,team,resource,rows,stamp){await env.DB.prepare(`INSERT INTO app_resources(team_id,resource,data_json,updated_at) VALUES(?,?,?,?) ON CONFLICT(team_id,resource) DO UPDATE SET data_json=excluded.data_json,updated_at=excluded.updated_at`).bind(String(team.id),resource,JSON.stringify(sanitizeResource(resource,rows)),stamp).run();}
async function syncTeamSnap(env,{full=true}={}){const cfg=await appConfig(env);if(!cfg?.teamsnap_token_enc)throw new ApiError('Connect TeamSnap from /admin first.',409,'teamsnap_not_configured');const token=await decryptSecret(env,cfg.teamsnap_token_enc),started=now();await env.DB.prepare(`UPDATE app_config SET sync_status='syncing',sync_error=NULL,updated_at=? WHERE id=?`).bind(started,APP_ID).run();try{const mePayload=await tsJson(`${TEAMSNAP_API}/me`,token),me=tsCollectionObjects(mePayload)[0]||{};if(me.id==null)throw new ApiError('TeamSnap did not return an account identity.',502,'teamsnap_identity_missing');let searched=[],related=[];try{searched=await tsFetchCollection('teams/search',{user_id:me.id},token);}catch{}const rel=await Promise.allSettled(discoverTsTeamUrls(mePayload,me).map(u=>tsFetchCollection(u,{},token)));for(const r of rel)if(r.status==='fulfilled')related.push(...r.value);const map=new Map();for(const t of [...searched,...related])if(t?.id!=null)map.set(String(t.id),{...(map.get(String(t.id))||{}),...t});const saved=await env.DB.prepare('SELECT data_json FROM app_teams').all();for(const r of saved.results||[]){const t=safeJsonParse(r.data_json,{});if(t?.id!=null&&serverTeamArchived(t)&&!map.has(String(t.id)))map.set(String(t.id),t);}const teams=[...map.values()];if(!teams.length)throw new ApiError('No TeamSnap teams are available for this account.',409,'teamsnap_no_teams');const stamp=now();await env.DB.prepare('DELETE FROM app_teams').run();for(const t of teams){const dataset=await ensureDataset(env,t);await env.DB.prepare(`INSERT INTO app_teams(team_id,dataset_id,data_json,updated_at) VALUES(?,?,?,?)`).bind(String(t.id),dataset.dataset_id,JSON.stringify(sanitizeTeam(t)),stamp).run();}const targetTeams=full?teams:teams.filter(t=>!serverTeamArchived(t));let failures=0;for(let i=0;i<targetTeams.length;i+=3){const batch=targetTeams.slice(i,i+3);await Promise.all(batch.map(async team=>{const resources=['events','members','locations','opponents','availabilities'],results=await Promise.allSettled(resources.map(r=>tsFetchCollection(`${r}/search`,{team_id:team.id,...(r==='events'?{sort_start_date:'asc'}:{})},token)));for(let j=0;j<resources.length;j++){const r=results[j];if(r.status==='fulfilled')await saveTeamResource(env,team,resources[j],r.value,stamp);else failures++;}}));}const status=failures?'partial':'ready',error=failures?`${failures} TeamSnap resource update${failures===1?'':'s'} failed; previously saved data was kept where available.`:null;await env.DB.prepare(`UPDATE app_config SET teamsnap_user_id=?,last_sync_at=?,updated_at=?,sync_status=?,sync_error=? WHERE id=?`).bind(String(me.id),stamp,stamp,status,error,APP_ID).run();return{ok:true,teams:teams.length,sync_status:status,sync_error:error,last_sync_at:stamp};}catch(e){await env.DB.prepare(`UPDATE app_config SET sync_status='error',sync_error=?,updated_at=? WHERE id=?`).bind(clean(e?.message)||'TeamSnap sync failed.',now(),APP_ID).run();throw e;}}
async function connectTeamSnap(request,env){await requireAdmin(request,env);const b=await bodyJson(request),token=clean(b.access_token),clientId=clean(b.client_id);if(!token)throw new ApiError('TeamSnap did not return an access token.',400,'teamsnap_token_missing');const mePayload=await tsJson(`${TEAMSNAP_API}/me`,token),me=tsCollectionObjects(mePayload)[0]||{};if(me.id==null)throw new ApiError('TeamSnap connection could not be verified.',401,'teamsnap_auth_required');const prior=await appConfig(env),enc=await encryptSecret(env,token),t=now();await env.DB.prepare(`INSERT INTO app_config(id,teamsnap_token_enc,teamsnap_client_id,teamsnap_user_id,include_preseason,connected_at,updated_at,sync_status,sync_error) VALUES(?,?,?,?,?,?,?,?,NULL) ON CONFLICT(id) DO UPDATE SET teamsnap_token_enc=excluded.teamsnap_token_enc,teamsnap_client_id=excluded.teamsnap_client_id,teamsnap_user_id=excluded.teamsnap_user_id,updated_at=excluded.updated_at,sync_status='connected',sync_error=NULL`).bind(APP_ID,enc,clientId,String(me.id),Number(prior?.include_preseason||0),prior?.connected_at||t,t,'connected').run();const result=await syncTeamSnap(env);return json({...result,viewer_urls:await datasetLinks(request,env)});}
async function publicBootstrap(env,access){const cfg=await appConfig(env),q=access?.admin?env.DB.prepare('SELECT data_json FROM app_teams ORDER BY team_id'):env.DB.prepare('SELECT data_json FROM app_teams WHERE dataset_id=? ORDER BY team_id').bind(access.dataset_id),result=await q.all(),teams=(result.results||[]).map(r=>safeJsonParse(r.data_json,{})).filter(t=>t?.id!=null);return json({configured:!!cfg?.teamsnap_token_enc&&teams.length>0,teams,last_sync_at:cfg?.last_sync_at||null,sync_status:cfg?.sync_status||'not_configured',sync_error:cfg?.sync_error||null,settings:{include_preseason:!!Number(cfg?.include_preseason||0)},dataset:access?.admin?null:{family_key:access?.family_key||null,display_name:access?.display_name||null},version:APP_VERSION});}
async function publicTeam(env,teamId,access){const id=clean(teamId);if(!id)throw new ApiError('Missing team.',400);const t=access?.admin?await env.DB.prepare('SELECT data_json,updated_at FROM app_teams WHERE team_id=?').bind(id).first():await env.DB.prepare('SELECT data_json,updated_at FROM app_teams WHERE team_id=? AND dataset_id=?').bind(id,access.dataset_id).first();if(!t)throw new ApiError('That team is not available from this viewer link.',404,'team_not_found');const rr=await env.DB.prepare('SELECT resource,data_json,updated_at FROM app_resources WHERE team_id=?').bind(id).all(),out={team:safeJsonParse(t.data_json,{}),updated_at:t.updated_at};for(const r of rr.results||[])out[r.resource]=safeJsonParse(r.data_json,[]);for(const k of['events','members','locations','opponents','availabilities'])if(!Array.isArray(out[k]))out[k]=[];return json(out);}
async function adminStatus(request,env){const cfg=await appConfig(env),teams=await env.DB.prepare('SELECT COUNT(*) AS n FROM app_teams').first();return json({ok:true,configured:!!cfg?.teamsnap_token_enc&&Number(teams?.n||0)>0,last_sync_at:cfg?.last_sync_at||null,sync_status:cfg?.sync_status||'not_configured',sync_error:cfg?.sync_error||null,teams:Number(teams?.n||0),client_id:cfg?.teamsnap_client_id||null,viewer_urls:await datasetLinks(request,env),settings:{include_preseason:!!Number(cfg?.include_preseason||0)},version:APP_VERSION});} 
async function saveAppSettings(request,env){const b=await bodyJson(request),value=b.include_preseason===true?1:0,t=now();const cfg=await appConfig(env);if(!cfg)throw new ApiError('Connect TeamSnap before changing dashboard settings.',409,'not_configured');await env.DB.prepare('UPDATE app_config SET include_preseason=?,updated_at=? WHERE id=?').bind(value,t,APP_ID).run();return json({ok:true,settings:{include_preseason:!!value}});} 
