async function traceTeamGames(cookie,token,team){const teamId=Number(team?.team_id);if(!Number.isFinite(teamId))throw new ApiError('Trace team identity is incomplete.',502,'trace_team_identity_invalid');const d=await traceGraphql(cookie,'teamGames',TEAM_GAMES_QUERY,{team_id:teamId,token});return Array.isArray(d.teamGames)?d.teamGames:[];}
