function startTraceBackground(ctx,env,key,owner,{refreshCatalog=false,retryErrors=false,gameLimit=BACKGROUND_INITIAL_GAMES}={}){if(!ctx?.waitUntil||!keyOk(key)||!owner)return;ctx.waitUntil(syncTeam(env,key,{owner,gameLimit,refreshCatalog,retryErrors}).catch(e=>console.error('Trace background sync failed',key,e)));}
async function maybeContinueTrace(env,ctx,key,owner){if(!ctx?.waitUntil||!keyOk(key)||!owner)return;const conn=await ownedConnection(env,key,owner);if(!conn||clean(conn.sync_status)==='auth_expired')return;const prog=await traceProgress(env,key);if(prog.pending>0||prog.collecting>0){startTraceBackground(ctx,env,key,owner,{refreshCatalog:false,gameLimit:BACKGROUND_INITIAL_GAMES});return;}const meta=safeJsonParse(conn.meta_json,{}),age=Date.now()-Date.parse(meta.catalog_updated_at||conn.last_sync_at||0);if(!Number.isFinite(age)||age>=CATALOG_REFRESH_MS)startTraceBackground(ctx,env,key,owner,{refreshCatalog:true,gameLimit:BACKGROUND_INITIAL_GAMES});}
